        /**
          * One draw2 detect on `source` PLUS the bbox crop mapped back to source pixels — the tap-to-add path (a confirmed still → identity + upload-ready crop).
         */
        "detectAndCrop": (source: HTMLCanvasElement, minConfidence?: number) => Promise<{ detection: Draw2Detection | null; crop: string | null; }>;
        /**
          * One draw2 detect on `source` → best pick above `minConfidence` (or null).
         */
        "detectFrame": (source: HTMLCanvasElement, minConfidence?: number) => Promise<Draw2Detection | null>;
        /**
          * Longest edge (px) of the frame POSTed to draw2 /detect (~1–2s vs ~6s).
          * @default 640
         */
        "detectMaxEdge": number;
        /**
          * Mac draw2 service URL. '' → streaming disabled (barcode/QR + Phase-1 only). May be the tailnet draw2 host directly (hub) OR the bucket-bot draw2 PROXY base (`.../api/hub/cards/draw2`) when `authToken` is set (off-tailnet).
          * @default ''
         */
        "draw2Url": string;
        /**
          * Optional SECONDARY draw2 proxy origin. When set, the scanner probes both `draw2Url` and `draw2UrlFallback` in parallel and uses whichever's `/health` is reachable — for YGO 245's complementary on/off-tailnet origins (the public Tailscale Funnel works only OFF the tailnet, `bot.popcorn245.com` only ON it), re-selecting live if connectivity flips. Hub omits it → unchanged single-origin (`draw2Url`) behavior.
         */
        "draw2UrlFallback"?: string;
        /**
          * @default 'environment'
         */
